// APTITUDE SYSTEM
// APTITUDE QUESTIONS
const questionBank = {
	Percentages: [
		{ question: 'A shirt costs ₹800. If the price increases by 10%, what is the new price?', options: ['₹820', '₹860', '₹880', '₹900'], answer: 2, steps: ['10% of ₹800 = ₹80', 'New price = ₹800 + ₹80', 'New price = ₹880'], shortcut: 'For a 10% increase, multiply by 1.10.', mistake: 'You may have found 10% correctly but added the wrong value.' },
		{ question: 'A number is increased by 20% and becomes 240. What was the original number?', options: ['180', '200', '220', '288'], answer: 1, steps: ['After the increase, 120% = 240', 'Original = 240 × 100 / 120', 'Original = 200'], shortcut: 'Reverse a percentage increase with final × 100 / (100 + increase).', mistake: 'The final value represents 120%, not 100%.' }
	],
	'Profit and Loss': [{ question: 'A product bought for ₹500 is sold for ₹600. What is the profit percentage?', options: ['10%', '15%', '20%', '25%'], answer: 2, steps: ['Profit = ₹600 − ₹500 = ₹100', 'Profit% = (Profit / Cost Price) × 100', 'Profit% = (100 / 500) × 100 = 20%'], shortcut: 'Profit percentage always uses cost price as the base.', mistake: 'Using the selling price as the base changes the percentage.' }],
	Average: [{ question: 'The average of 12, 18 and 24 is:', options: ['16', '18', '20', '54'], answer: 1, steps: ['Add the values: 12 + 18 + 24 = 54', 'Count the values: 3', 'Average = 54 / 3 = 18'], shortcut: 'Average = total ÷ number of values.', mistake: 'Remember to divide the total by the count, not by the largest value.' }],
	'Ratio and Proportion': [{ question: 'The ratio of boys to girls is 2:3. If there are 20 boys, how many girls are there?', options: ['25', '30', '35', '40'], answer: 1, steps: ['2 parts represent 20 boys', '1 part = 20 / 2 = 10', 'Girls = 3 parts = 3 × 10 = 30'], shortcut: 'Find the value of one part before finding the required parts.', mistake: 'The ratio must be scaled by the same multiplier on both sides.' }],
	'Time and Work': [{ question: 'A can finish a job in 10 days. What fraction of the job does A complete in one day?', options: ['1/5', '1/10', '10', '10% of a day'], answer: 1, steps: ['Whole work = 1', 'A takes 10 days', 'One-day work = 1 / 10'], shortcut: 'If a person takes n days, one-day work is 1/n.', mistake: 'Days and work rate are reciprocal, so use division rather than multiplication.' }],
	'Time, Speed and Distance': [{ question: 'A car travels at 60 km/h for 2 hours. How far does it travel?', options: ['30 km', '62 km', '120 km', '180 km'], answer: 2, steps: ['Distance = Speed × Time', 'Distance = 60 × 2', 'Distance = 120 km'], shortcut: 'Keep the three-unit triangle: distance = speed × time.', mistake: 'Speed and time are multiplied to find distance.' }],
	Probability: [{ question: 'A fair coin is tossed once. What is the probability of getting heads?', options: ['0', '1/4', '1/2', '1'], answer: 2, steps: ['Favourable outcomes = 1 (heads)', 'Total outcomes = 2 (heads or tails)', 'Probability = 1 / 2'], shortcut: 'Probability = favourable outcomes ÷ total equally likely outcomes.', mistake: 'The denominator must include every possible outcome.' }],
	'Number System': [{ question: 'What is the remainder when 17 is divided by 5?', options: ['1', '2', '3', '4'], answer: 1, steps: ['5 × 3 = 15', '17 − 15 = 2', 'The remainder is 2'], shortcut: 'Subtract the largest multiple of the divisor that does not exceed the number.', mistake: 'The quotient is 3, but the question asks for the remainder.' }],
	'Number Series': [{ question: 'Find the next number: 3, 6, 12, 24, ?', options: ['30', '36', '48', '60'], answer: 2, steps: ['Each number is multiplied by 2', '24 × 2 = 48', 'The next number is 48'], shortcut: 'Compare consecutive terms to find a repeated operation.', mistake: 'Look for the pattern between terms, not only their difference.' }],
	'Coding-Decoding': [{ question: 'If CAT is coded as DBU by moving each letter one step forward, DOG becomes:', options: ['EPH', 'FQI', 'CNE', 'EOG'], answer: 0, steps: ['D moves to E', 'O moves to P and G moves to H', 'DOG becomes EPH'], shortcut: 'Write the alphabet beside each letter and apply the same shift.', mistake: 'The same rule must be applied to every letter.' }],
	'Synonyms': [{ question: 'Choose the word closest in meaning to "brief":', options: ['Long', 'Short', 'Loud', 'Bright'], answer: 1, steps: ['Brief means lasting for a short time or using few words', 'The closest option is Short'], shortcut: 'Use the sentence meaning, not only a familiar sound.', mistake: 'Brief is about length or duration, not volume.' }]
};

