	'Quantitative Aptitude': ['Number System', 'HCF and LCM', 'Simplification', 'Percentages', 'Profit and Loss', 'Simple Interest', 'Compound Interest', 'Ratio and Proportion', 'Average', 'Time and Work', 'Pipes and Cisterns', 'Time, Speed and Distance', 'Problems on Trains', 'Boats and Streams', 'Mixtures and Allegations', 'Partnership', 'Ages', 'Permutation and Combination', 'Probability', 'Algebra', 'Geometry', 'Mensuration', 'Data Interpretation'],
	'Logical Reasoning': ['Number Series', 'Letter Series', 'Analogy', 'Classification', 'Coding-Decoding', 'Blood Relations', 'Direction Sense', 'Ranking', 'Syllogisms', 'Statements and Conclusions', 'Statements and Assumptions', 'Seating Arrangement', 'Puzzles', 'Venn Diagrams', 'Data Sufficiency', 'Clocks', 'Calendars'],
