const aptitudeFallback = topic => ({ question: `Which statement is the best first step when solving a ${topic} problem?`, options: ['Read the question carefully and identify the given values', 'Choose the longest option', 'Skip the units', 'Guess immediately'], answer: 0, steps: ['Read the question once without calculating', 'Underline the known values and what is asked', 'Choose the relevant concept or formula'], shortcut: 'Understand the question before choosing a formula.', mistake: 'Jumping to an option before identifying the given information can lead to a guess.' });

function generateAptitudeQuestion(topic = 'Percentages', difficulty = 'Easy', seed = 0) { const list = questionBank[topic] || [aptitudeFallback(topic)]; const item = list[Math.abs(seed) % list.length]; return { id: `${topic}-${difficulty}-${seed}-${item.question}`, topic, difficulty, ...item }; }
function getTopicTeaching(topic, language = 'tanglish') { const english = { title: `Learn ${topic}`, concept: `${topic} becomes easier when you identify the given values first and connect them to one clear rule.`, formula: topic === 'Percentages' ? 'Percentage = (Part / Total) × 100' : topic === 'Average' ? 'Average = Total ÷ Number of values' : topic === 'Time, Speed and Distance' ? 'Distance = Speed × Time' : 'Read the question → choose the formula → substitute values → check the units.', example: topic === 'Percentages' ? '50 out of 200: 50 / 200 × 100 = 25%' : topic === 'Average' ? 'For 10, 20, 30: total 60 ÷ 3 = 20' : 'Start with a small example, then apply the same method to the question.', shortcut: 'Basic method first. Shortcut only after you understand what each value means.', mistakes: 'Do not rush the formula, ignore units, or calculate before understanding what the question asks.' }; if (language === 'tamil') return { ...english, concept: `${topic}-ஐ solve செய்ய முதலில் given values-ஐ கண்டுபிடித்து, சரியான rule-ஐ பயன்படுத்த வேண்டும்.`, formula: english.formula, example: english.example, shortcut: 'முதலில் basic method கற்றுக்கொள்ளுங்கள். பிறகு shortcut பயன்படுத்தலாம்.', mistakes: 'Question என்ன கேட்கிறது என்பதைப் புரிந்துகொள்ளாமல் calculation தொடங்க வேண்டாம்.' }; if (language === 'tanglish') return { ...english, concept: `${topic}-la first given values identify pannunga. Appuram one clear rule or formula use pannina easy-ah solve pannalaam.`, formula: english.formula, example: topic === 'Percentages' ? '50 out of 200: 50 / 200 × 100 = 25%' : 'Small example-la same method apply pannunga.', shortcut: 'Basic method first. Concept purinjadhukku apram shortcut use pannunga.', mistakes: 'Question enna kekkudhu-nu paakama formula apply pannadheenga.' }; return english; }
function analyzeMistake(question, selectedIndex, language = 'tanglish') { const correct = selectedIndex === question.answer; if (correct) return language === 'tamil' ? 'சரியான answer. Method-ஐ புரிந்து பயன்படுத்தியிருக்கிறீர்கள்.' : language === 'english' ? 'Your choice matches the verified answer and method.' : 'Correct choice. Method-um right-ah use pannirukeenga.'; const selected = question.options[selectedIndex] || 'No answer'; const base = question.mistake; if (language === 'tamil') return `உங்கள் answer: ${selected}. ${base} Concept-ஐ மீண்டும் ஒரு similar question மூலம் practice செய்வோம்.`; if (language === 'english') return `Your answer was ${selected}. ${base} We will reinforce the concept with a similar question.`; return `Unga answer ${selected}. ${base} Same concept-la innoru similar question try pannalaam.`; }
function generateSimilarQuestion(question, seed = 1) { return generateAptitudeQuestion(question.topic, question.difficulty, seed); }
function generateSolution(question) { return { answer: question.options[question.answer], steps: question.steps, shortcut: question.shortcut }; }
function generatePracticeSet(topics = [], count = 5, difficulty = 'Easy') { const list = topics.length ? topics : ['Percentages']; return Array.from({ length: count }, (_, index) => generateAptitudeQuestion(list[index % list.length], difficulty, index)); }
function generateMockTest(count = 25) { return generatePracticeSet(['Percentages', 'Profit and Loss', 'Time and Work', 'Number Series', 'Synonyms'], count, 'Placement'); }
function generateWeakAreaQuestions(stats = {}, count = 5) { const weak = Object.entries(stats.byTopic || {}).sort((a, b) => a[1].accuracy - b[1].accuracy).map(item => item[0]); return generatePracticeSet(weak.length ? weak : ['Percentages'], count); }
function generateExplanation(question, language = 'tanglish') { return analyzeMistake(question, question.answer, language); }
function generateShortcut(topic) { return getTopicTeaching(topic).shortcut; }
function generateStudyPlan(stats = {}) { const weak = Object.entries(stats.byTopic || {}).sort((a, b) => a[1].accuracy - b[1].accuracy).slice(0, 3).map(item => item[0]); const topics = weak.length ? weak : ['Percentages', 'Profit and Loss', 'Time and Work']; return topics.map((topic, index) => ({ day: index + 1, topic, target: index === 2 ? '20-question mixed practice' : `${15 + index * 5} focused questions` })); }
function getFormulaMatches(search = '') { const formulas = { Percentage: 'Percentage = (Part / Total) × 100', 'Profit and Loss': 'Profit% = (Profit / Cost Price) × 100', Interest: 'Simple Interest = (P × R × T) / 100', 'Time and Work': 'One-day work = 1 / Number of days', 'Speed Distance Time': 'Distance = Speed × Time', Average: 'Average = Total ÷ Count', Ratio: 'Scale both ratio parts by the same multiplier', Probability: 'Probability = Favourable outcomes ÷ Total outcomes', 'Permutation and Combination': 'nPr = n! / (n-r)! and nCr = n! / (r!(n-r)!)', Mensuration: 'Area and volume depend on the shape-specific formula' }; return Object.entries(formulas).filter(([name, formula]) => `${name} ${formula}`.toLowerCase().includes(search.toLowerCase())); }

