const storedAptitude = JSON.parse(localStorage.getItem('interviewmate-aptitude') || 'null');
const state = { view: 'home', language: localStorage.getItem('interviewmate-language') || 'tanglish', setup: {}, questionIndex: 0, attempts: [], transcript: '', listening: false, startedAt: null, history: JSON.parse(localStorage.getItem(storageKey) || '[]'), settings: { autoSpeak: true, autoListen: false, speed: 1, voice: 'auto' }, aptitude: storedAptitude || { screen: 'dashboard', topic: 'Percentages', difficulty: 'Easy', mode: 'practice', question: null, selected: null, submitted: false, questionIndex: 0, session: [], mockAnswers: [], mockStarted: null, questionStarted: null, doubtAnswer: '' }, aptitudeStats: JSON.parse(localStorage.getItem('interviewmate-aptitude-stats') || '{"attempted":0,"correct":0,"totalSeconds":0,"streak":0,"byTopic":{}}') };
languageSelect.value = state.language;
document.querySelector('#footerYear').textContent = new Date().getFullYear();

function t(key) { return copy[state.language][key] || copy.tanglish[key] || key; }
function esc(value = '') { return value.replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[char])); }
function notify(message) { toast.textContent = message; toast.classList.add('show'); setTimeout(() => toast.classList.remove('show'), 2600); }
function saveState() { localStorage.setItem(storageKey, JSON.stringify(state.history)); localStorage.setItem('interviewmate-language', state.language); }
function setView(view) { state.view = view; render(); window.scrollTo({ top: 0, behavior: 'smooth' }); }
function render() { document.querySelectorAll('.nav-link').forEach(button => button.classList.toggle('active', button.dataset.view === state.view)); const views = { home: renderHome, setup: renderSetup, prepare: renderPrepare, aptitude: renderAptitude, progress: renderProgress, interview: renderInterview }; app.innerHTML = views[state.view](); bindViewEvents(); }

// INTERVIEW SYSTEM
function renderHome() { return `<section class="view"><div class="page-heading"><span class="eyebrow">PERSONAL INTERVIEW TRAINER / 001</span><h1>${t('hero')}</h1><p>${t('subtitle')}</p><div class="button-row"><button class="button button-primary" data-action="setup">${t('start')} <span>↗</span></button><button class="button button-secondary" data-action="practice">${t('practice')}</button></div></div><div class="hero-grid"><div class="hero-card primary"><span class="eyebrow">YOUR ADVANTAGE</span><h2>Learn the answer. Own the room.</h2><p>InterviewMate listens, teaches, and gives you a better way to say what you already know.</p><div class="orb"></div></div><div class="hero-card stat"><div><span class="eyebrow">YOUR PRACTICE RHYTHM</span><div class="stat-number">${state.history.length}</div><div class="stat-label">interviews completed</div></div><div class="mini-bars"><i></i><i></i><i></i><i></i><i></i></div></div></div><div class="section-title"><div><span class="eyebrow">THE COACHING LOOP</span><h2>Everything you need to get interview ready.</h2></div></div><div class="feature-grid">${featureData.map(item => `<article class="feature"><div class="feature-icon">${item[0]}</div><h3>${item[1]}</h3><p>${item[2]}</p></article>`).join('')}</div></section>`; }

function renderSetup() { return `<section class="view"><div class="page-heading"><span class="eyebrow">STEP 01 / SETUP</span><h1>${t('setup')}</h1><p>${t('setupHint')}</p></div><div class="form-layout"><form class="panel form-panel" id="setupForm"><span class="eyebrow">YOUR TARGET</span><h2>Make it specific.</h2><div class="form-grid"><div class="field"><label for="company">${t('company')} *</label><input id="company" name="company" placeholder="e.g. Zoho, Freshworks" required></div><div class="field"><label for="role">${t('role')} *</label><input id="role" name="role" placeholder="e.g. Frontend Developer" required></div><div class="field full"><label for="description">Job description</label><textarea id="description" name="description" placeholder="Paste the role description or describe what the job involves."></textarea></div><div class="field"><label for="skills">Skills</label><input id="skills" name="skills" placeholder="JavaScript, SQL, communication"></div><div class="field"><label for="experience">Experience level</label><select id="experience" name="experience"><option>Student / fresher</option><option>0–2 years</option><option>3–5 years</option><option>5+ years</option></select></div></div><div class="form-footer"><span class="hint">* Required. You can change these details anytime.</span><button class="button button-primary" type="submit">${t('begin')} ↗</button></div></form><aside class="panel"><span class="eyebrow">CHOOSE YOUR FORMAT</span><h2>How should we practice?</h2><p class="hint">The first version of your session will use these choices to shape the coaching.</p><div class="choice-list"><label class="choice"><input type="radio" name="type" value="Mixed" checked> Mixed interview</label><label class="choice"><input type="radio" name="type" value="HR"> HR & behavioral</label><label class="choice"><input type="radio" name="type" value="Technical"> Technical</label><label class="choice"><input type="radio" name="type" value="Resume Based"> Resume based</label></div><div style="height:20px"></div><span class="eyebrow">DIFFICULTY</span><div class="choice-list" style="margin-top:10px"><label class="choice"><input type="radio" name="difficulty" value="Beginner"> Beginner</label><label class="choice"><input type="radio" name="difficulty" value="Intermediate" checked> Intermediate</label><label class="choice"><input type="radio" name="difficulty" value="Advanced"> Advanced</label></div></aside></div></section>`; }

function makeQuestions() { const role = state.setup.role || 'this role'; const skills = state.setup.skills || 'your key skills'; return [`Tell me about yourself and why you are interested in ${role}.`, `Walk me through one project where you used ${skills.split(',')[0] || 'your skills'}.`, `What is one challenge you faced, and how did you solve it?`, `Why should we choose you for this role?`]; }
function renderPrepare() { const role = state.setup.role || 'your target role'; const company = state.setup.company || 'your target company'; return `<section class="view"><div class="page-heading"><span class="eyebrow">STEP 02 / YOUR BRIEF</span><h1>${t('prepare')}</h1><p>Here is a practical map for ${esc(role)} at ${esc(company)}. No invented company facts, just the areas your role points to.</p></div><div class="prep-grid"><article class="panel prep-panel"><div class="prep-meta"><div><span>COMPANY</span><strong>${esc(company)}</strong></div><div><span>ROLE</span><strong>${esc(role)}</strong></div></div><span class="eyebrow">WHAT TO PREPARE</span><h2>Build your answer shelf.</h2><ul><li>Introduce your education, skills, and the kind of work you want to do.</li><li>Prepare one project with the problem, your role, technology, and result.</li><li>Review ${esc(state.setup.skills || 'the core skills in the job description')} with simple examples.</li><li>Practice one teamwork story using Situation, Task, Action, and Result.</li></ul></article><article class="panel prep-panel"><span class="eyebrow">YOUR CHECKLIST</span><h2>Before you enter the room.</h2><ul class="checklist"><li>Tell me about yourself in 60–90 seconds</li><li>Explain one project without reading a script</li><li>Connect one skill to how you can contribute</li><li>Keep a real example ready for a challenge</li><li>End answers with a clear result or learning</li></ul><div class="button-row"><button class="button button-primary" data-action="beginInterview">Enter mock interview ↗</button><button class="button button-secondary" data-action="setup">Edit setup</button></div></article></div></section>`; }

function aptText(key) { const words = { english: { title: 'Aptitude Preparation', subtitle: 'Build your speed, accuracy and problem-solving skills for placement tests.', learn: 'Learn with AI', practice: 'Quick Practice', mock: 'Timed Mock Test', weak: 'Weak Areas', plan: 'Your practice plan', ask: 'Ask AI', start: 'Start Practice', teach: 'Teach Again', ready: 'Ready? Start a practice question', correct: 'Correct! Your method is working.', wrong: 'Let\'s see where it went wrong.', next: 'Next question', similar: 'Try a similar question', solution: 'Show solution', dashboard: 'Back to aptitude dashboard' }, tanglish: { title: 'Aptitude Preparation', subtitle: 'Placement tests-ku speed, accuracy and problem-solving skills build pannunga.', learn: 'Learn with AI', practice: 'Quick Practice', mock: 'Timed Mock Test', weak: 'Weak Areas', plan: 'Unga practice plan', ask: 'Ask AI', start: 'Start Practice', teach: 'Teach Again', ready: 'Ready-ah? Practice question start pannalaam', correct: 'Correct! Unga method work aagudhu.', wrong: 'Enga mistake aachu-nu step by step paakalam.', next: 'Next question', similar: 'Same concept-la similar question', solution: 'Show solution', dashboard: 'Aptitude dashboard-ku back' }, tamil: { title: 'Aptitude Preparation', subtitle: 'Placement tests-க்காக speed, accuracy மற்றும் problem-solving skills வளர்த்துக் கொள்ளுங்கள்.', learn: 'AI-யுடன் கற்றுக்கொள்ளுங்கள்', practice: 'Quick Practice', mock: 'Timed Mock Test', weak: 'Weak Areas', plan: 'உங்கள் practice plan', ask: 'AI-யிடம் கேளுங்கள்', start: 'Practice தொடங்கு', teach: 'மீண்டும் கற்றுக்கொள்', ready: 'Ready-ஆ? Practice question தொடங்கலாம்', correct: 'Correct! உங்கள் method சரியாக உள்ளது.', wrong: 'எங்கே mistake என்பதை step by step பார்க்கலாம்.', next: 'அடுத்த கேள்வி', similar: 'அதே concept-ல் similar question', solution: 'Solution பார்க்க', dashboard: 'Aptitude dashboard-க்கு திரும்பு' } }; return words[state.language]?.[key] || words.tanglish[key] || key; }
function saveAptitude() { localStorage.setItem('interviewmate-aptitude', JSON.stringify(state.aptitude)); localStorage.setItem('interviewmate-aptitude-stats', JSON.stringify(state.aptitudeStats)); }
function aptitudeAccuracy() { return state.aptitudeStats.attempted ? Math.round(state.aptitudeStats.correct / state.aptitudeStats.attempted * 100) : 0; }
function selectedAptitudeTopics() { return state.aptitude.topic === 'All Topics' ? Object.values(TOPIC_GROUPS).flat() : [state.aptitude.topic]; }
function startAptitudePractice(topic = state.aptitude.topic, mode = 'practice') { state.aptitude.screen = 'practice'; state.aptitude.mode = mode; state.aptitude.topic = topic; state.aptitude.questionIndex = 0; state.aptitude.selected = null; state.aptitude.submitted = false; state.aptitude.question = generateAptitudeQuestion(topic, state.aptitude.difficulty, 0); state.aptitude.session = []; state.aptitude.questionStarted = Date.now(); saveAptitude(); setView('aptitude'); }
// APTITUDE AI
function renderAptitude() { const screens = { dashboard: renderAptitudeDashboard, learn: renderAptitudeLearn, practice: renderAptitudePractice, mock: renderAptitudeMock, result: renderAptitudeResult }; return (screens[state.aptitude.screen] || renderAptitudeDashboard)(); }
function renderAptitudeDashboard() { const stats = state.aptitudeStats; const topics = Object.entries(TOPIC_GROUPS); const weak = Object.entries(stats.byTopic).sort((a, b) => a[1].accuracy - b[1].accuracy)[0]?.[0] || 'Time and Work'; const plan = generateStudyPlan(stats); return `<section class="view aptitude-view"><div class="page-heading"><span class="eyebrow">PLACEMENT PREPARATION / 002</span><h1>${aptText('title')}</h1><p>${aptText('subtitle')}</p></div><div class="aptitude-actions"><button class="button button-primary" data-apt-action="learn">✦ ${aptText('learn')}</button><button class="button button-secondary" data-apt-action="practice">◎ ${aptText('practice')}</button><button class="button button-secondary" data-apt-action="adaptive">◌ Adaptive</button><button class="button button-secondary" data-apt-action="daily">◇ Daily Practice</button><button class="button button-secondary" data-apt-action="mock">◷ ${aptText('mock')}</button><button class="button button-secondary" data-apt-action="weak">↗ ${aptText('weak')}</button></div><div class="aptitude-metrics"><article class="panel"><span class="eyebrow">QUESTIONS SOLVED</span><strong>${stats.attempted}</strong><span>Keep building the habit.</span></article><article class="panel"><span class="eyebrow">ACCURACY</span><strong>${aptitudeAccuracy()}%</strong><span>Across saved practice.</span></article><article class="panel"><span class="eyebrow">AVERAGE TIME</span><strong>${stats.attempted ? Math.round(stats.totalSeconds / stats.attempted) : 0}s</strong><span>Per question</span></article><article class="panel"><span class="eyebrow">CURRENT STREAK</span><strong>${stats.streak}</strong><span>Correct answers in a row</span></article></div><div class="aptitude-grid"><article class="panel topic-library"><div class="section-title"><div><span class="eyebrow">TOPIC LIBRARY</span><h2>Choose what to strengthen.</h2></div></div>${topics.map(([group, list]) => `<div class="topic-group"><h3>${group}</h3><div class="topic-chips"><button class="topic-chip selected" data-apt-topic="${list[0]}">${list[0]}</button>${list.slice(1).map(topic => `<button class="topic-chip" data-apt-topic="${topic}">${topic}</button>`).join('')}</div></div>`).join('')}</article><aside class="aptitude-side"><article class="panel"><span class="eyebrow">NEEDS PRACTICE</span><h2>${weak}</h2><p class="hint">Your weakest tracked topic. We will teach the idea before another attempt.</p><button class="button button-primary" data-apt-action="weak">Practice weak areas ↗</button></article><article class="panel"><span class="eyebrow">${aptText('plan').toUpperCase()}</span><h2>Five focused days.</h2>${plan.map(item => `<div class="plan-row"><b>DAY ${item.day}</b><span>${item.topic}</span><small>${item.target}</small></div>`).join('')}</article><article class="panel"><span class="eyebrow">${aptText('ask').toUpperCase()}</span><h2>Stuck on a step?</h2><form id="aptitudeDoubtForm"><input id="aptitudeDoubt" placeholder="Why did we divide by 120?" aria-label="Ask an aptitude doubt"><button class="button button-secondary" type="submit">Ask ↗</button></form><p class="doubt-answer">${esc(state.aptitude.doubtAnswer || 'Ask about a formula, option, or mistake.')}</p><button class="small-control" data-apt-action="voiceDoubt">♩ Ask by voice</button></article></aside></div></section>`; }
function renderAptitudeLearn() { const teaching = getTopicTeaching(state.aptitude.topic, state.language); return `<section class="view aptitude-view"><div class="page-heading"><span class="eyebrow">AI APTITUDE TEACHER / ${state.aptitude.topic.toUpperCase()}</span><h1>${teaching.title}</h1><p>${teaching.concept}</p></div><div class="learn-grid"><article class="panel lesson-card"><span class="eyebrow">THE IDEA</span><h2>Understand before you calculate.</h2><p>${teaching.concept}</p><div class="formula-box">${teaching.formula}</div><h3>Simple example</h3><p>${teaching.example}</p></article><aside class="panel lesson-card"><span class="eyebrow">SHORTCUT & CARE</span><h2>Use the shortcut wisely.</h2><p><b>Shortcut:</b> ${teaching.shortcut}</p><p><b>Common mistake:</b> ${teaching.mistakes}</p><div class="button-row"><button class="button button-primary" data-apt-action="startLearn">${aptText('ready')} ↗</button><button class="button button-secondary" data-apt-action="teachAgain">${aptText('teach')}</button></div></aside></div><button class="text-button" data-apt-action="dashboard">← ${aptText('dashboard')}</button></section>`; }
// APTITUDE PRACTICE
function renderAptitudePractice() { const q = state.aptitude.question || generateAptitudeQuestion(state.aptitude.topic, state.aptitude.difficulty); const result = state.aptitude.submitted; const selected = state.aptitude.selected; const correct = selected === q.answer; return `<section class="view aptitude-view"><div class="practice-top"><div><span class="eyebrow">${state.aptitude.mode === 'weak' ? 'WEAK AREA PRACTICE' : 'FOCUSED PRACTICE'}</span><h1>${q.topic}</h1></div><div class="question-meta"><span>${q.difficulty}</span><span>Question ${state.aptitude.questionIndex + 1}</span></div></div><div class="practice-layout"><article class="panel question-card"><div class="question-label">QUESTION</div><h2>${q.question}</h2><div class="answer-options">${q.options.map((option, index) => `<button class="answer-option ${result && index === q.answer ? 'right' : ''} ${result && index === selected && index !== q.answer ? 'wrong' : ''}" data-apt-answer="${index}" ${result ? 'disabled' : ''}><b>${String.fromCharCode(65 + index)}</b><span>${option}</span></button>`).join('')}</div>${result ? `<div class="answer-feedback ${correct ? 'success' : 'failure'}"><h3>${correct ? aptText('correct') : aptText('wrong')}</h3><p>${analyzeMistake(q, selected, state.language)}</p><p><b>Your answer:</b> ${q.options[selected] || 'Skipped'}<br><b>Correct answer:</b> ${q.options[q.answer]}</p></div><div class="solution-panel"><h3>${aptText('solution')}</h3>${generateSolution(q).steps.map((step, i) => `<p><b>Step ${i + 1}:</b> ${step}</p>`).join('')}<p><b>Shortcut:</b> ${q.shortcut}</p></div><div class="button-row">${correct ? `<button class="button button-primary" data-apt-action="next">${aptText('next')} ↗</button>` : `<button class="button button-primary" data-apt-action="similar">${aptText('similar')} ↗</button>`}<button class="button button-secondary" data-apt-action="dashboard">${aptText('dashboard')}</button></div>` : `<p class="hint">Choose one answer. The solution stays hidden until you commit.</p>`}</article><aside class="panel tutor-side"><span class="eyebrow">AI TUTOR</span><h2>Think out loud.</h2><p>First identify what the question gives you. Then choose the formula. Speed comes after accuracy.</p><div class="tutor-tip">${getTopicTeaching(q.topic, state.language).formula}</div><div class="difficulty-row"><span>Difficulty</span><select id="aptDifficulty"><option ${state.aptitude.difficulty === 'Easy' ? 'selected' : ''}>Easy</option><option ${state.aptitude.difficulty === 'Medium' ? 'selected' : ''}>Medium</option><option ${state.aptitude.difficulty === 'Hard' ? 'selected' : ''}>Hard</option><option ${state.aptitude.difficulty === 'Placement' ? 'selected' : ''}>Placement</option></select></div></aside></div></section>`; }
// APTITUDE MOCK TEST
function renderAptitudeMock() { const questions = state.aptitude.session; const current = questions[state.aptitude.questionIndex]; if (!current) return renderAptitudeDashboard(); return `<section class="view aptitude-view"><div class="practice-top"><div><span class="eyebrow">TIMED PLACEMENT MOCK</span><h1>Stay calm. Keep moving.</h1></div><div class="mock-clock" id="aptMockTimer">30:00</div></div><div class="practice-layout"><article class="panel question-card"><div class="question-label">QUESTION ${state.aptitude.questionIndex + 1} / ${questions.length}</div><h2>${current.question}</h2><div class="answer-options">${current.options.map((option, index) => `<button class="answer-option ${state.aptitude.mockAnswers[state.aptitude.questionIndex] === index ? 'selected' : ''}" data-mock-answer="${index}"><b>${String.fromCharCode(65 + index)}</b><span>${option}</span></button>`).join('')}</div><div class="button-row"><button class="button button-secondary" data-apt-action="previous" ${state.aptitude.questionIndex === 0 ? 'disabled' : ''}>← Previous</button><button class="button button-secondary" data-apt-action="mark">Mark for review</button>${state.aptitude.questionIndex === questions.length - 1 ? `<button class="button button-primary" data-apt-action="finishMock">Submit test ↗</button>` : `<button class="button button-primary" data-apt-action="mockNext">Next ↗</button>`}</div></article><aside class="panel palette"><span class="eyebrow">QUESTION PALETTE</span><div>${questions.map((_, i) => `<button class="palette-number ${i === state.aptitude.questionIndex ? 'current' : ''} ${state.aptitude.mockAnswers[i] !== undefined ? 'answered' : ''}" data-mock-jump="${i}">${i + 1}</button>`).join('')}</div><p class="hint">Solutions stay hidden until you submit the complete test.</p></aside></div></section>`; }
function renderAptitudeResult() { const answers = state.aptitude.mockAnswers; const questions = state.aptitude.session; const attempted = answers.filter(answer => answer !== undefined).length; const correct = answers.filter((answer, i) => answer !== undefined && answer === questions[i].answer).length; return `<section class="view aptitude-view"><div class="page-heading"><span class="eyebrow">MOCK TEST COMPLETE</span><h1>Good work showing up.</h1><p>Here is a clear review of your attempt. Use it to decide what to practice next.</p></div><div class="result-metrics"><article class="panel"><strong>${questions.length}</strong><span>Total questions</span></article><article class="panel"><strong>${attempted}</strong><span>Attempted</span></article><article class="panel"><strong>${correct}</strong><span>Correct</span></article><article class="panel"><strong>${attempted ? Math.round(correct / attempted * 100) : 0}%</strong><span>Accuracy</span></article></div><div class="result-grid"><article class="panel"><span class="eyebrow">PERFORMANCE</span><h2>Strong areas and next steps.</h2><div class="metric"><div class="metric-top"><span>Mixed aptitude</span><span>${attempted ? Math.round(correct / attempted * 100) : 0}%</span></div><div class="bar"><i style="width:${attempted ? Math.round(correct / attempted * 100) : 0}%"></i></div></div><p class="hint">${correct < attempted ? 'Review the marked questions and repeat their concepts in focused practice.' : 'Excellent accuracy. Try the next difficulty or a shorter timer.'}</p></article><article class="panel"><span class="eyebrow">RECOMMENDED</span><h2>${aptText('plan')}</h2>${generateStudyPlan(state.aptitudeStats).map(item => `<div class="plan-row"><b>DAY ${item.day}</b><span>${item.topic}</span><small>${item.target}</small></div>`).join('')}<button class="button button-primary" data-apt-action="dashboard">${aptText('dashboard')}</button></article></div></section>`; }

function renderInterview() { const questions = makeQuestions(); const question = questions[state.questionIndex % questions.length]; const latest = state.attempts[state.attempts.length - 1]; return `<section class="view"><div class="interview-layout"><div class="panel interview-room"><div class="room-header"><div><span class="eyebrow">LIVE PRACTICE</span><br><strong>${esc(state.setup.company || 'Interview')}</strong> · ${esc(state.setup.role || 'your role')}</div><div class="question-count">${state.questionIndex + 1} / ${questions.length}<br><span id="timer">00:00</span></div></div><div class="avatar-zone"><div class="avatar-ring ${state.listening ? 'listening' : ''}"><div class="avatar-core"><i></i></div></div><div class="status" id="voiceStatus">${state.listening ? t('listening') : t('ready')}</div></div><div class="question-box"><div class="label">${t('question').toUpperCase()}</div><h2>${esc(question)}</h2></div><div class="mic-row"><button class="mic-button ${state.listening ? 'active' : ''}" id="micButton" aria-label="${state.listening ? 'Stop listening' : 'Start listening'}">♩</button><div class="room-controls"><button class="small-control" data-action="repeat">↻ Repeat</button><button class="small-control" data-action="togglePause">Ⅱ Pause</button><button class="small-control" data-action="endInterview">End</button></div></div><div class="transcript"><strong>You:</strong><span id="liveTranscript">${esc(state.transcript || 'Your transcript will appear here as you speak, or type below.')}</span></div><div class="field" style="margin-top:12px"><label for="textAnswer">Text fallback</label><textarea id="textAnswer" rows="3" placeholder="${t('answer')}"></textarea><button class="button button-secondary" id="submitAnswer" style="align-self:flex-start;margin-top:8px">${t('submit')} ↗</button></div></div><aside class="panel feedback-panel"><span class="eyebrow">${t('feedback').toUpperCase()}</span><h2>${latest ? latest.title : 'Your teacher is ready.'}</h2>${latest ? renderFeedback(latest) : `<div class="feedback-section"><h3>HOW THIS WORKS</h3><p>Answer naturally. I will look at your idea, structure, clarity, and one speaking habit. Then I will show you a stronger version and invite you to try again.</p></div><div class="feedback-section highlight"><h3>START HERE</h3><p>Use the microphone or type a short answer below. There is no exam score.</p></div>`}</aside></div></section>`; }
function renderFeedback(feedback) { return [['WHAT YOU SAID', feedback.what], ['WHAT YOU DID WELL', feedback.good], ['WHAT NEEDS IMPROVEMENT', feedback.issue], ['WHY', feedback.why], ['HOW TO IMPROVE', feedback.how], ['BETTER ANSWER', feedback.better], ['EASY SPEAKING VERSION', feedback.easy], ['SPEAKING TIP', feedback.tip]].map((item, index) => `<div class="feedback-section ${index === 5 ? 'highlight' : ''}"><h3>${item[0]}</h3><p>${esc(item[1])}</p></div>`).join('') + `<div class="button-row"><button class="button button-primary" data-action="retry">${t('retry')}</button><button class="button button-secondary" data-action="nextQuestion">${t('next')} ↗</button></div>`; }

function renderProgress() { const count = state.history.length; return `<section class="view"><div class="page-heading"><span class="eyebrow">YOUR PRACTICE LOG</span><h1>${t('progressTitle')}</h1><p>${t('progressText')}</p></div><div class="progress-grid"><article class="panel"><div class="score-card"><div class="score">${count}</div><div><strong>${t('sessions')}</strong><p>Keep showing up. Confidence grows from familiar reps, not perfect first attempts.</p></div></div><div class="metric"><div class="metric-top"><span>Answer structure</span><span>68%</span></div><div class="bar"><i style="width:68%"></i></div></div><div class="metric"><div class="metric-top"><span>Project explanation</span><span>54%</span></div><div class="bar"><i style="width:54%"></i></div></div><div class="metric"><div class="metric-top"><span>Speaking clarity</span><span>76%</span></div><div class="bar"><i style="width:76%"></i></div></div></article><article class="panel"><span class="eyebrow">${t('recent').toUpperCase()}</span><h2>${t('keep')}</h2>${count ? state.history.slice(-5).reverse().map(item => `<div class="history-row"><div><strong>${esc(item.role)}</strong><span>${esc(item.company)} · ${item.date}</span></div><span class="tag">${item.language}</span></div>`).join('') : `<div class="feedback-section"><p class="hint">Your completed sessions will appear here. Start with one honest answer.</p></div>`}</article></div></section>`; }

// AI INTERVIEW
function getFeedback(answer) { const short = answer.trim().split(/\s+/).length < 8; const role = state.setup.role || 'this role'; const lang = state.language; if (lang === 'tamil') return { title: short ? 'நல்ல தொடக்கம். இன்னும் கொஞ்சம் விரிவாக சொல்லலாம்.' : 'உங்கள் பதில் நல்ல direction-ல் உள்ளது.', what: answer, good: 'உங்கள் முக்கிய idea தெளிவாக உள்ளது. நீங்கள் நேராக பதில் சொல்ல முயற்சி செய்தது நல்லது.', issue: short ? 'பதில் மிகவும் short-ஆக உள்ளது. ஒரு example அல்லது skill சேர்க்க வேண்டும்.' : 'உங்கள் பதிலில் ஒரு specific example மற்றும் result இன்னும் missing.', why: 'Interviewer உங்கள் answer-ல் நீங்கள் உண்மையில் என்ன செய்தீர்கள் என்பதைப் புரிந்துகொள்ள விரும்புவார்.', how: 'Point-ஐ சொல்லுங்கள், அதற்கு ஒரு project example கொடுங்கள், கடைசியில் result அல்லது learning சொல்லுங்கள்.', better: `நான் ${role}-க்கு interested, ஏனெனில் இந்த role-ல் என் skills-ஐ பயன்படுத்த முடியும். என் project-ல் ஒரு real problem-ஐ solve செய்தேன், அதனால் team-க்கு contribute செய்ய முடியும்.`, easy: `இந்த role எனக்கு பிடிக்கும். என் skills-ஐ பயன்படுத்தி real projects-ல் contribute செய்ய விரும்புகிறேன்.`, tip: 'ஒரு sentence-ல் ஒரு idea மட்டும் சொல்லுங்கள். மெதுவாகவும் தெளிவாகவும் பேசுங்கள்.' }; if (lang === 'english') return { title: short ? 'You are on the right track. Let’s add one layer.' : 'Your answer has a clear direction.', what: answer, good: 'You answered the question directly and your main idea is understandable.', issue: short ? 'The answer is very short. Add one skill, example, or result.' : 'It needs a specific example and a clear result to feel more credible.', why: 'Interviewers need evidence of how you work, not only what you want.', how: 'Start with your point, add one project example, and finish with the result or learning.', better: `I am interested in ${role} because it matches my skills and the kind of work I want to do. In one project, I used my skills to solve a practical problem, and I learned how to contribute more effectively to a team.`, easy: `I am interested in this role because it matches my skills. I want to work on real projects and contribute to the team.`, tip: 'Pause for one second before you begin. Give one idea per sentence.' }; return { title: short ? 'Main idea correct. Konjam detail add pannalaam.' : 'Unga answer-ku clear direction irukku.', what: answer, good: 'Neenga question-ku direct-ah answer panna try pannirukeenga. Main idea puriyudhu.', issue: short ? 'Answer romba short-ah irukku. One skill, example, illa result add pannunga.' : 'Specific example and clear result miss aayirukku.', why: 'Interviewer-ku neenga epdi work pannuveenga-nu evidence venum. Wish mattum pothaadhu.', how: 'First main point sollunga, next one project example, last-la result illa learning sollunga.', better: `I am interested in ${role} because it matches my skills. One project-la practical problem solve pannirukken, so team-ku contribute panna mudiyum-nu namburen.`, easy: `Indha role en skills-ku match aagudhu. Real projects-la work panni team-ku contribute panna virumburen.`, tip: 'Start panna before one small pause edunga. One sentence-la one idea sollunga.' }; }

function submitAnswer(answer) { if (!answer.trim()) return notify(t('empty')); state.transcript = answer; const feedback = getFeedback(answer); state.attempts.push(feedback); localStorage.setItem('interviewmate-last-attempt', JSON.stringify(state.attempts)); render(); notify('Coaching is ready. Read it once, then try again.'); }
function startTimer() { const timer = document.querySelector('#timer'); if (!timer || state.timer) return; state.timer = setInterval(() => { if (!state.startedAt) state.startedAt = Date.now(); const seconds = Math.floor((Date.now() - state.startedAt) / 1000); timer.textContent = `${String(Math.floor(seconds / 60)).padStart(2, '0')}:${String(seconds % 60).padStart(2, '0')}`; }, 1000); }
// VOICE SYSTEM
function startListening() { const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition; if (!Recognition) return notify('Voice recognition is not supported here. Use the text fallback below.'); state.listening = true; render(); const recognition = new Recognition(); recognition.lang = state.language === 'tamil' ? 'ta-IN' : 'en-IN'; recognition.interimResults = true; recognition.continuous = false; recognition.onresult = event => { const result = [...event.results].map(item => item[0].transcript).join(''); state.transcript = result; const live = document.querySelector('#liveTranscript'); if (live) live.textContent = result; }; recognition.onerror = () => { state.listening = false; notify('Parava illa. Voice clear-ah detect aagala. Type your answer instead.'); render(); }; recognition.onend = () => { state.listening = false; const answer = state.transcript; render(); if (answer) submitAnswer(answer); }; recognition.start(); state.recognition = recognition; }
function speakAI(text) { if (!window.speechSynthesis) return notify('Speech output is not supported in this browser.'); window.speechSynthesis.cancel(); const utterance = new SpeechSynthesisUtterance(text.replace(/[*#_`]/g, '')); utterance.rate = Number(state.settings.speed); utterance.lang = state.language === 'tamil' ? 'ta-IN' : 'en-IN'; window.speechSynthesis.speak(utterance); }
function submitAptitudeAnswer(selected) { const q = state.aptitude.question; if (!q || state.aptitude.submitted) return; state.aptitude.selected = selected; state.aptitude.submitted = true; const seconds = Math.max(1, Math.round((Date.now() - (state.aptitude.questionStarted || Date.now())) / 1000)); const stats = state.aptitudeStats; const topicStats = stats.byTopic[q.topic] || { attempted: 0, correct: 0, accuracy: 0 }; const correct = selected === q.answer; stats.attempted += 1; stats.correct += correct ? 1 : 0; stats.totalSeconds += seconds; stats.streak = correct ? stats.streak + 1 : 0; topicStats.attempted += 1; topicStats.correct += correct ? 1 : 0; topicStats.accuracy = Math.round(topicStats.correct / topicStats.attempted * 100); stats.byTopic[q.topic] = topicStats; state.aptitude.session.push({ question: q.id, selected, correct, seconds }); if (state.aptitude.mode === 'adaptive') { const levels = ['Easy', 'Medium', 'Hard', 'Placement']; const current = levels.indexOf(state.aptitude.difficulty); state.aptitude.difficulty = levels[Math.max(0, Math.min(levels.length - 1, current + (correct ? 1 : -1)))]; } saveAptitude(); render(); }
function startAptitudeVoiceDoubt() { const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition; if (!Recognition) return notify('Voice recognition is not supported here. Type your doubt instead.'); const recognition = new Recognition(); recognition.lang = state.language === 'tamil' ? 'ta-IN' : 'en-IN'; recognition.onresult = event => { const spoken = event.results[0][0].transcript; state.aptitude.doubtAnswer = state.language === 'tamil' ? `${spoken} என்பதற்கு: முதலில் final value எந்த percentage என்பதை identify செய்யுங்கள். Formula-வை substitute செய்து step by step solve பண்ணலாம்.` : state.language === 'english' ? `${spoken}: first identify which percentage the final value represents, then substitute it into the formula and solve step by step.` : `${spoken}: first final value enna percentage-nu identify pannunga. Formula-la substitute panni step by step solve pannalaam.`; saveAptitude(); render(); }; recognition.onerror = () => notify('Voice doubt clear-ah detect aagala. Type it instead.'); recognition.start(); notify('Listening for your aptitude doubt...'); }
function startAptitudeMockTimer() { clearInterval(state.aptitude.mockTimer); state.aptitude.mockSeconds = 1800; state.aptitude.mockTimer = setInterval(() => { state.aptitude.mockSeconds -= 1; const timer = document.querySelector('#aptMockTimer'); if (timer) timer.textContent = `${String(Math.floor(state.aptitude.mockSeconds / 60)).padStart(2, '0')}:${String(state.aptitude.mockSeconds % 60).padStart(2, '0')}`; if (state.aptitude.mockSeconds <= 0) { clearInterval(state.aptitude.mockTimer); state.aptitude.screen = 'result'; render(); } }, 1000); }
function bindViewEvents() { document.querySelectorAll('[data-action="setup"]').forEach(item => item.onclick = () => setView('setup')); document.querySelectorAll('[data-action="practice"]').forEach(item => item.onclick = () => setView('setup')); document.querySelectorAll('[data-action="beginInterview"]').forEach(item => item.onclick = () => { state.view = 'interview'; state.questionIndex = 0; state.attempts = []; state.transcript = ''; state.startedAt = Date.now(); render(); startTimer(); }); const form = document.querySelector('#setupForm'); if (form) form.onsubmit = event => { event.preventDefault(); const data = new FormData(form); state.setup = Object.fromEntries(data.entries()); state.setup.type = document.querySelector('input[name="type"]:checked')?.value || 'Mixed'; state.setup.difficulty = document.querySelector('input[name="difficulty"]:checked')?.value || 'Intermediate'; setView('prepare'); }; const submit = document.querySelector('#submitAnswer'); if (submit) submit.onclick = () => submitAnswer(document.querySelector('#textAnswer').value); const mic = document.querySelector('#micButton'); if (mic) mic.onclick = () => state.listening ? state.recognition?.stop() : startListening(); document.querySelectorAll('[data-action="retry"]').forEach(item => item.onclick = () => { state.transcript = ''; render(); }); document.querySelectorAll('[data-action="nextQuestion"]').forEach(item => item.onclick = () => { state.questionIndex += 1; state.transcript = ''; state.attempts = []; render(); startTimer(); }); document.querySelectorAll('[data-action="repeat"]').forEach(item => item.onclick = () => speakAI(makeQuestions()[state.questionIndex % makeQuestions().length])); document.querySelectorAll('[data-action="endInterview"]').forEach(item => item.onclick = () => { state.history.push({ company: state.setup.company || 'Practice', role: state.setup.role || 'Interview', language: state.language, date: new Date().toLocaleDateString() }); saveState(); clearInterval(state.timer); state.timer = null; setView('progress'); notify('Interview saved to your progress.'); }); bindAptitudeEvents(); }

function bindAptitudeEvents() { document.querySelectorAll('[data-apt-topic]').forEach(button => button.onclick = () => { state.aptitude.topic = button.dataset.aptTopic; saveAptitude(); render(); }); document.querySelectorAll('[data-apt-action="dashboard"]').forEach(button => button.onclick = () => { state.aptitude.screen = 'dashboard'; render(); }); document.querySelectorAll('[data-apt-action="learn"]').forEach(button => button.onclick = () => { state.aptitude.screen = 'learn'; render(); }); document.querySelectorAll('[data-apt-action="teachAgain"]').forEach(button => button.onclick = () => render()); document.querySelectorAll('[data-apt-action="startLearn"]').forEach(button => button.onclick = () => startAptitudePractice(state.aptitude.topic, 'learned')); document.querySelectorAll('[data-apt-action="practice"]').forEach(button => button.onclick = () => startAptitudePractice(state.aptitude.topic, 'practice')); document.querySelectorAll('[data-apt-action="adaptive"]').forEach(button => button.onclick = () => { state.aptitude.mode = 'adaptive'; startAptitudePractice(state.aptitude.topic, 'adaptive'); }); document.querySelectorAll('[data-apt-action="daily"]').forEach(button => button.onclick = () => startAptitudePractice(['Percentages', 'Number Series', 'Synonyms'][new Date().getDate() % 3], 'daily')); document.querySelectorAll('[data-apt-action="weak"]').forEach(button => button.onclick = () => { const weak = Object.entries(state.aptitudeStats.byTopic).sort((a, b) => a[1].accuracy - b[1].accuracy)[0]?.[0] || 'Percentages'; startAptitudePractice(weak, 'weak'); }); document.querySelectorAll('[data-apt-action="mock"]').forEach(button => button.onclick = () => { state.aptitude.screen = 'mock'; state.aptitude.questionIndex = 0; state.aptitude.mockAnswers = []; state.aptitude.session = ['Percentages', 'Profit and Loss', 'Time and Work', 'Number Series', 'Synonyms'].map((topic, index) => generateAptitudeQuestion(topic, index % 2 ? 'Medium' : 'Easy', index)); state.aptitude.mockStarted = Date.now(); saveAptitude(); render(); startAptitudeMockTimer(); }); document.querySelectorAll('[data-apt-answer]').forEach(button => button.onclick = () => submitAptitudeAnswer(Number(button.dataset.aptAnswer))); document.querySelectorAll('[data-apt-action="next"]').forEach(button => button.onclick = () => { state.aptitude.questionIndex += 1; state.aptitude.question = generateAptitudeQuestion(state.aptitude.topic, state.aptitude.difficulty, state.aptitude.questionIndex); state.aptitude.selected = null; state.aptitude.submitted = false; state.aptitude.questionStarted = Date.now(); render(); }); document.querySelectorAll('[data-apt-action="similar"]').forEach(button => button.onclick = () => { state.aptitude.question = generateSimilarQuestion(state.aptitude.question, state.aptitude.questionIndex + 1); state.aptitude.selected = null; state.aptitude.submitted = false; state.aptitude.questionIndex += 1; state.aptitude.questionStarted = Date.now(); render(); }); const difficulty = document.querySelector('#aptDifficulty'); if (difficulty) difficulty.onchange = () => { state.aptitude.difficulty = difficulty.value; state.aptitude.question = generateAptitudeQuestion(state.aptitude.topic, state.aptitude.difficulty); state.aptitude.submitted = false; state.aptitude.selected = null; render(); }; document.querySelectorAll('[data-mock-answer]').forEach(button => button.onclick = () => { state.aptitude.mockAnswers[state.aptitude.questionIndex] = Number(button.dataset.mockAnswer); render(); }); document.querySelectorAll('[data-mock-jump]').forEach(button => button.onclick = () => { state.aptitude.questionIndex = Number(button.dataset.mockJump); render(); }); document.querySelectorAll('[data-apt-action="mockNext"]').forEach(button => button.onclick = () => { state.aptitude.questionIndex += 1; render(); }); document.querySelectorAll('[data-apt-action="previous"]').forEach(button => button.onclick = () => { state.aptitude.questionIndex -= 1; render(); }); document.querySelectorAll('[data-apt-action="finishMock"]').forEach(button => button.onclick = () => { clearInterval(state.aptitude.mockTimer); state.aptitude.screen = 'result'; saveAptitude(); render(); }); const doubtForm = document.querySelector('#aptitudeDoubtForm'); if (doubtForm) doubtForm.onsubmit = event => { event.preventDefault(); const question = document.querySelector('#aptitudeDoubt').value.trim(); if (!question) return; state.aptitude.doubtAnswer = state.language === 'tamil' ? '120% என்பது 20% increase-க்கு பிறகு வரும் final value. அதனால் final value 240 என்றால் 100% = 240 × 100 / 120.' : state.language === 'english' ? '120% represents the value after a 20% increase. If 120% is 240, then 100% is 240 × 100 / 120.' : '120% means 20% increase-ku apram varra final value. 120% = 240 na, 100% = 240 × 100 / 120.'; saveAptitude(); render(); }; document.querySelectorAll('[data-apt-action="voiceDoubt"]').forEach(button => button.onclick = () => startAptitudeVoiceDoubt()); }

document.querySelectorAll('.nav-link').forEach(button => button.onclick = () => setView(button.dataset.view));
languageSelect.onchange = () => { state.language = languageSelect.value; localStorage.setItem('interviewmate-language', state.language); render(); notify('Language updated.'); };
document.querySelector('#settingsButton').onclick = () => settingsDialog.showModal(); document.querySelector('#closeSettings').onclick = () => settingsDialog.close(); document.querySelector('#saveSettings').onclick = () => { state.settings.autoSpeak = document.querySelector('#autoSpeak').checked; state.settings.autoListen = document.querySelector('#autoListen').checked; state.settings.speed = document.querySelector('#speedSelect').value; settingsDialog.close(); notify(t('saved')); };
render();
